WITH (SELECT mapFromArrays(groupArray(id), groupArray(name)) FROM (SELECT id, argMax(name, release) AS name FROM item_names GROUP BY id)) AS inames, z AS (SELECT id, any(name) AS zname FROM zone_names GROUP BY id) SELECT s.kind AS kind, s.zone_id AS zone, z.zname AS zone_name, s.place AS place, s.model AS model, s.ids AS ids, arrayMap(i -> inames[i], s.ids) AS id_names, s.rows AS rows, s.log AS log, s.n AS n, s.captures AS captures, s.capture_id AS capture_id, s.ts_ms AS ts_ms, inames[{item:Int64}] AS item_name FROM item_sources(item = {item:Int64}) s LEFT JOIN z ON z.id = s.zone_id ORDER BY s.kind, s.n DESC
